145	    protected long registrar(Compra compra) throws Exception {
146	        MvcResult resultado = postar("/pedidos", compra.json());
147	        if (resultado.getResponse().getStatus() != 201) {
148	            throw new AssertionError("Pedido não registrado: " + corpo(resultado));
149	        }
150	        return ((Number) ler(resultado, "$.id")).longValue();
151	    }
152	
153	    protected MvcResult pagar(long id, String idTransacao, String pagoEm) throws Exception {
154	        return postar("/pedidos/" + id + "/pagamento", "{\"idTransacao\": \"" + idTransacao + "\", \"pagoEm\": \"" + pagoEm + "\"}");
155	    }
156	
157	    protected MvcResult pagarAgora(long id, String idTransacao) throws Exception {
158	        String criadoEm = ler(consultar("/pedidos/" + id), "$.criadoEm");
159	        return pagar(id, idTransacao, criadoEm);
160	    }
161	
162	    protected int estoque(String sku) throws Exception {
163	        return ler(consultar("/produtos/" + sku), "$.estoque");
164	    }
165	
166	    protected Map<String, Object> mapa(MvcResult resultado, String caminho) throws Exception {
167	        return ler(resultado, caminho);
168	    }
169	
170	
171	    public static final class Compra {
172	        private final String cpf;
173	        private final String[] itens;
174	        String cep = "01310100";
175	        String regiao = "SUDESTE";
176	        String modalidade = "RETIRADA_LOJA";
177	        String cupom;
178	        String forma = "PIX";
179	        Integer parcelas;
180	        String nivel = "BRONZE";
181	
182	        Compra(String cpf, String... itens) {
183	            this.cpf = cpf;
184	            this.itens = itens;
185	        }
186	
187	        public Compra cep(String v) { cep = v; return this; }
188	        public Compra regiao(String v) { regiao = v; return this; }
189	        public Compra entrega(String v) { modalidade = v; return this; }
190	        public Compra cupom(String v) { cupom = v; return this; }
191	        public Compra pagamento(String v) { forma = v; return this; }
192	        public Compra parcelas(int v) { parcelas = v; return this; }
193	        public Compra nivel(String v) { nivel = v; return this; }
194	
195	        public String json() {
196	            StringBuilder itensJson = new StringBuilder();
197	            for (int i = 0; i < itens.length; i += 2) {
198	                if (i > 0) {
199	                    itensJson.append(", ");
200	                }
201	                itensJson.append("{\"sku\": \"").append(itens[i]).append("\", \"quantidade\": ").append(itens[i + 1]).append("}");
202	            }
203	            return "{"
204	                    + "\"cliente\": {\"cpf\": \"" + cpf + "\", \"email\": \"cliente@exemplo.com\"},"
205	                    + "\"itens\": [" + itensJson + "],"
206	                    + texto("cep", cep) + texto("regiao", regiao) + texto("modalidadeEntrega", modalidade)
207	                    + texto("cupom", cupom) + texto("formaPagamento", forma) + texto("nivelClube", nivel)
208	                    + (parcelas == null ? "" : "\"parcelas\": " + parcelas + ",")
209	                    + "\"fim\": true}";
210	        }
211	
212	        private static String texto(String campo, String valor) {
213	            return valor == null ? "" : "\"" + campo + "\": \"" + valor + "\",";
214	        }
215	    }
216	}

